                // Continuation lines indented two or more past the content column.
                if lines.iter().skip(1).any(|l| indent_of(l) >= 2) {
                    return false;
                }
                para_count += 1;
                if depth > 0 && para_count > 1 {
                    return false;
                }
            }
            _ => {}
        }
    }
    true
}

