#[derive(Debug, Clone, PartialEq)]
pub enum DirKind {
    Skip,
    SkipFile,
    Off,
    On,
    Markdown(Vec<String>),
    Embedded(String),
    /// Option-only directive such as `canonical=true`.
    Options(Vec<String>),
    /// Align the next sequence of flow mappings (`true`: collapse block rows first).
    Table(bool),
    /// Enable or disable compaction with a scope.
    Compact(bool, Scope),
    Other,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Scope {
    Next,
    FromHere,
    File,
}

#[derive(Debug, Clone)]
pub struct Directive {
    pub line: usize,
    pub col: usize,
    pub kind: DirKind,
}

#[derive(Debug, Default)]
pub struct Directives {
    pub skip_file: bool,
    /// Inclusive line ranges kept verbatim (from `off` to `on`).
    pub off_regions: Vec<(usize, usize)>,
    /// Lines holding `skip` directives.
    pub skip_lines: Vec<usize>,
    pub markdown: Vec<(usize, Vec<String>)>,
    pub options: Vec<(usize, Vec<String>)>,
    pub embedded: Vec<(usize, String)>,
    /// Table directives (line, collapse block rows).
    pub tables: Vec<(usize, bool)>,
    /// Compaction directives (line, enabled, scope).
    pub compacts: Vec<(usize, bool, Scope)>,
}

fn err(line: usize, col: usize, msg: impl Into<String>) -> Diagnostic {
    Diagnostic { line: line + 1, col: col + 1, msg: msg.into() }
}

/// Parse the text of a comment (starting at '#'). Returns None if not a directive.
pub fn parse_comment(text: &str, line: usize, col: usize) -> Option<Result<Directive, Diagnostic>> {
    let body = text.strip_prefix('#')?.trim();
    let rest = body.strip_prefix("fmt:")?.trim();
    let words: Vec<&str> = rest.split_whitespace().collect();
    if words.is_empty() {
        return Some(Err(err(line, col, "invalid fmt directive: empty")));
    }
    for w in &words {
        if let Some(sc) = w.strip_prefix("scope=") {
            if !matches!(sc, "next" | "from-here" | "file") {
                return Some(Err(err(line, col, format!("invalid fmt directive scope: {}", sc))));
            }
        }
    }
    let kind = match words[0] {
        "skip" => match &words[1..] {
            [] | ["scope=next"] => DirKind::Skip,
            ["file"] | ["scope=file"] => DirKind::SkipFile,
            _ => return Some(Err(err(line, col, "invalid fmt: skip directive"))),
        },
        "off" => match &words[1..] {
            [] | ["scope=from-here"] => DirKind::Off,
            _ => return Some(Err(err(line, col, "invalid fmt: off directive"))),
        },
        "on" => {
            if words.len() > 1 {
                if words[1].starts_with("scope=") {
                    return Some(Err(err(line, col, "fmt: on does not support explicit scope")));
                }
                return Some(Err(err(line, col, "invalid fmt: on directive")));
            }
            DirKind::On
        }
        "markdown" | "md" => DirKind::Markdown(words[1..].iter().map(|s| s.to_string()).collect()),
        "embedded" => {
            if words.len() < 2 {
                return Some(Err(err(line, col, "invalid fmt: embedded directive")));
            }
            DirKind::Embedded(words[1].to_string())
        }
        w if w == "table" || w == "compact" || w.starts_with("compact=") => match table_or_compact(&words) {
            Ok(k) => k,
            Err(m) => return Some(Err(err(line, col, m))),
        },
        w if w.contains('=') || w == "canonical" => DirKind::Options(words.iter().map(|s| s.to_string()).collect()),
        w if w.starts_with("template.") => DirKind::Other,
        name => {
            if crate::source::formatter_program(name).is_none() {
                return Some(Err(err(line, col, format!("unknown embedded formatter: {}", name))));
            }
            DirKind::Embedded(name.to_string())
        }
    };
    Some(Ok(Directive { line, col, kind }))
}

fn table_or_compact(words: &[&str]) -> Result<DirKind, String> {
    let mut scope = Scope::Next;
    let mut scope_word = None;
    let mut rest: Vec<&str> = Vec::new();
    for w in words {
        match w.strip_prefix("scope=") {
            Some(sc) => {
                scope_word = Some(sc);
                scope = match sc {
                    "from-here" => Scope::FromHere,
                    "file" => Scope::File,
                    _ => Scope::Next,
                };
            }
            None => rest.push(w),
        }
    }
    let table = |rest: &[&str]| -> Result<DirKind, String> {
        let compact = match rest {
            [] => false,
            ["compact"] | ["compact=true"] => true,
            _ => return Err("invalid fmt: table directive".into()),
        };
        if let Some(sc) = scope_word.filter(|_| scope != Scope::Next) {
            return Err(format!("fmt: table does not support scope={}", sc));
        }
        Ok(DirKind::Table(compact))
    };
    if rest[0] == "table" {
        return table(&rest[1..]);
    }
    if let Some(v) = rest[0].strip_prefix("compact=") {
        let on = match v {
            "true" | "yes" | "1" => true,
            "false" | "no" | "0" => false,
            _ => return Err("invalid fmt: compact option".into()),
        };
