/// Take the pending directive (by line) that applies to a scalar starting at `line`.
fn take_dir<T: Clone>(dirs: &[(usize, T)], used: &mut Vec<usize>, line: usize) -> Option<T> {
    let mut found = None;
    for (l, v) in dirs {
        if *l < line && !used.contains(l) {
            found = Some((*l, v.clone()));
